const fs = require('fs');
const path = require('path');
const filePath = path.resolve(__dirname, '..', '3d-globe.html');
let html = fs.readFileSync(filePath, 'utf8');

function esc(s) { return (s ? String(s) : '').replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t'); }

function entry(la, ln, n, sub, desc, fact) {
  return '  {n:\'' + esc(n) + '\',la:' + la + ',ln:' + ln + ',sub:\'' + esc(sub) + '\',desc:\'' + esc(desc) + '\',fact:\'' + esc(fact) + '\'},';
}
function entryPts(n, sub, desc, fact, pts) {
  return '  {n:\'' + esc(n) + '\',sub:\'' + esc(sub) + '\',desc:\'' + esc(desc) + '\',fact:\'' + esc(fact) + '\',pts:' + JSON.stringify(pts) + '},';
}

function entryNE(n, sub, desc, fact) {
  return '  {n:\'' + esc(n) + '\',sub:\'' + esc(sub) + '\',desc:\'' + esc(desc) + '\',fact:\'' + esc(fact) + '\'},';
}

function entryLa(n, la, ln, sub, desc, fact) {
  return '  {n:\'' + esc(n) + '\',la:' + la + ',ln:' + ln + ',sub:\'' + esc(sub) + '\',desc:\'' + esc(desc) + '\',fact:\'' + esc(fact) + '\'},';
}

