for (const [cat, entries] of Object.entries(inserts)) {
  var marker = 'D.' + cat + ' = [';
  var startIdx = html.indexOf(marker);
  if (startIdx === -1) { console.log('ERROR: ' + cat + ' not found'); continue; }
  var afterBracket = html.indexOf('[', startIdx) + 1;
  var chunk = html.slice(afterBracket, afterBracket + 50000);
  var depth = 1, endIdx = 0;
  for (var i = 0; i < chunk.length; i++) {
    if (chunk[i] === '[') depth++;
    else if (chunk[i] === ']') { depth--; if (depth === 0) { endIdx = i; break; } }
  }
  var arrayContent = chunk.slice(0, endIdx);
  var existingCount = (arrayContent.match(/\{n:'/g) || []).length;
  var insertIdx = afterBracket + endIdx;
  if (existingCount >= entries.length) { console.log(cat + ': ' + existingCount + ' entries (all done)'); continue; }

  var insertStr = '';
  for (var j = existingCount; j < entries.length; j++) {
    insertStr += '\n' + entries[j];
  }
  if (insertStr) {
    html = html.slice(0, insertIdx) + insertStr + '\n' + html.slice(insertIdx);
  }
  console.log(cat + ': ' + existingCount + ' -> ' + (existingCount + (entries.length - existingCount)) + ' (added ' + (entries.length - existingCount) + ')');
}
